1	/**
2	 * Canal anônimo de denúncias — página pública, sem login, sem DashboardLayout.
3	 * Duas abas: "Fazer denúncia" e "Acompanhar".
4	 */
5	
6	import { useState, useRef } from 'react';
7	import { useForm } from 'react-hook-form';
8	import { zodResolver } from '@hookform/resolvers/zod';
9	import { z } from 'zod';
10	import { toast } from 'sonner';
11	import { Shield, Lock, Copy, CheckCircle, ChevronRight, Send, Loader2, Eye, EyeOff } from 'lucide-react';
12	import { format, parseISO } from 'date-fns';
13	import { ptBR } from 'date-fns/locale';
14	
15	import { Button } from '@/shared/ui/button';
16	import { Input } from '@/shared/ui/input';
17	import { Label } from '@/shared/ui/label';
18	import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/shared/ui/tabs';
19	import {
20	  Select,
21	  SelectContent,
22	  SelectItem,
23	  SelectTrigger,
24	  SelectValue,
25	} from '@/shared/ui/select';
26	import { GlassCard } from '@/shared/ui/glass-card';
27	import { MommaPageLayout } from '@/shared/ui/MommaPageLayout';
28	
29	import { CATEGORIAS_OUVIDORIA, labelCategoria, labelStatus } from '../lib/categorias';
30	import { LOJAS_OUVIDORIA } from '../lib/lojas';
31	import { useEnviarDenuncia } from '../model/useEnviarDenuncia';
32	import { useConsultarProtocolo } from '../model/useConsultarProtocolo';
33	import { useResponderProtocolo } from '../model/useResponderProtocolo';
34	import { MensagemBubble } from './MensagemBubble';
35	import { CategoriaBadge } from './CategoriaBadge';
36	import { StatusBadge } from './StatusBadge';
37	import type { CategoriaOuvidoria, ConsultaProtocoloResult, MensagemThread } from '../types';
38	
39	// ---------------------------------------------------------------------------
40	// Schema de denúncia
41	// ---------------------------------------------------------------------------
42	
43	const denunciaSchema = z.object({
44	  categoria: z.string({ required_error: 'Selecione uma categoria' }).min(1, 'Selecione uma categoria') as z.ZodType<CategoriaOuvidoria>,
45	  loja_id: z.string().optional(),
46	  mensagem: z
47	    .string({ required_error: 'Escreva sua mensagem' })
48	    .min(10, 'Mínimo de 10 caracteres')
49	    .max(5000, 'Máximo de 5.000 caracteres'),
50	  senha: z.string({ required_error: 'Crie uma senha de acompanhamento' }).min(4, 'Mínimo de 4 caracteres'),
51	  // Honeypot — nunca deve ser preenchido por humanos
52	  hp_field: z.string().optional(),
53	});
54	
55	type DenunciaFormValues = z.infer<typeof denunciaSchema>;
56	
57	// Schema de consulta de protocolo
58	const consultaSchema = z.object({
59	  protocolo: z.string({ required_error: 'Informe o protocolo' }).min(1, 'Informe o protocolo'),
60	  senha: z.string({ required_error: 'Informe a senha' }).min(1, 'Informe a senha'),
61	});
62	
63	type ConsultaFormValues = z.infer<typeof consultaSchema>;
64	
65	// ---------------------------------------------------------------------------
66	// Sub-componente: Formulário de denúncia
67	// ---------------------------------------------------------------------------
68	
69	interface FormDenunciaProps {
70	  onSuccess: (protocolo: string) => void;
71	  onAcompanhar: (protocolo: string) => void;
72	}
73	
74	function FormDenuncia({ onSuccess, onAcompanhar }: FormDenunciaProps) {
75	  const [protocolo, setProtocolo] = useState<string | null>(null);
76	  const [copiado, setCopiado] = useState(false);
77	  const [mostrarSenha, setMostrarSenha] = useState(false);
78	  const enviarDenuncia = useEnviarDenuncia();
79	
80	  const {
81	    register,
82	    handleSubmit,
83	    watch,
84	    setValue,
85	    formState: { errors },
86	    reset,
87	  } = useForm<DenunciaFormValues>({
88	    resolver: zodResolver(denunciaSchema),
89	    defaultValues: { hp_field: '' },
90	  });
91	
92	  const mensagemValue = watch('mensagem') ?? '';
93	
94	  const onSubmit = handleSubmit(async (values) => {
95	    // Honeypot: se preenchido, fingir sucesso sem enviar
96	    if (values.hp_field) {
97	      setProtocolo('XXX-FAKE-0000');
98	      return;
99	    }
100	
101	    try {
102	      const lojaId = values.loja_id && values.loja_id !== '__nao_informar'
103	        ? parseInt(values.loja_id, 10)
104	        : null;
105	
106	      const proto = await enviarDenuncia.mutateAsync({
107	        categoria: values.categoria,
108	        loja_id: lojaId,
109	        mensagem: values.mensagem,
110	        senha: values.senha,
111	      });
112	
113	      setProtocolo(proto);
114	      onSuccess(proto);
115	      reset();
116	    } catch (err) {
117	      toast.error((err as Error).message ?? 'Erro ao registrar denúncia');
118	    }
119	  });
120	
121	  const copiarProtocolo = async () => {
122	    if (!protocolo) return;
123	    try {
124	      await navigator.clipboard.writeText(protocolo);
125	      setCopiado(true);
126	      setTimeout(() => setCopiado(false), 2000);
127	    } catch {
128	      toast.error('Não foi possível copiar. Anote manualmente.');
129	    }
130	  };
131	
132	  if (protocolo) {
133	    return (
134	      <div className="flex flex-col gap-6">
135	        {/* Sucesso */}
136	        <div className="flex flex-col items-center gap-4 py-6">
137	          <div className="rounded-full bg-emerald-50 dark:bg-emerald-900/20 p-4">
138	            <CheckCircle className="h-8 w-8 text-emerald-600" />
139	          </div>
140	          <div className="text-center">
141	            <p className="text-lg font-semibold text-[#2D362E] dark:text-[#E6DCCF]">
142	              Denúncia registrada
143	            </p>
144	            <p className="text-sm text-muted-foreground mt-1">
145	              Seu protocolo de acompanhamento é:
146	            </p>
147	          </div>
148	          <div className="flex items-center gap-3">
149	            <span className="font-mono text-2xl font-bold text-[#57715B] tracking-widest">
150	              {protocolo}
151	            </span>
152	            <button
153	              type="button"
154	              data-mia-skip
155	              onClick={copiarProtocolo}
156	              className="rounded-xl p-2 hover:bg-[#57715B]/10 text-[#57715B] transition-colors"
157	              aria-label="Copiar protocolo"
158	            >
159	              {copiado ? <CheckCircle className="h-5 w-5 text-emerald-600" /> : <Copy className="h-5 w-5" />}
160	            </button>
161	          </div>
162	        </div>
163	
164	        {/* Callout de atenção */}
165	        <div className="rounded-2xl border border-amber-200 dark:border-amber-800/30 bg-amber-50 dark:bg-amber-900/10 p-4 flex gap-3">
166	          <Shield className="h-5 w-5 text-amber-600 flex-shrink-0 mt-0.5" />
167	          <div className="text-sm text-amber-700 dark:text-amber-400">
168	            <p className="font-semibold mb-1">Guarde o protocolo e a senha</p>
169	            <p>
170	              Esses dados são a <strong>única forma</strong> de acompanhar sua denúncia.
171	              Não há recuperação de senha. Recomendamos anotar em local seguro.
172	            </p>
173	          </div>
174	        </div>
175	
176	        {/* Ação: acompanhar */}
177	        <Button
178	          type="button"
179	          data-mia-skip
180	          onClick={() => onAcompanhar(protocolo)}
181	          className="w-full bg-[#57715B] hover:bg-[#465b49] text-white rounded-xl h-11 gap-2"
182	        >
183	          Acompanhar denúncia
184	          <ChevronRight className="h-4 w-4" />
185	        </Button>
186	      </div>
187	    );
188	  }
189	
190	  return (
191	    <form onSubmit={onSubmit} className="flex flex-col gap-5">
192	      {/* Callout de anonimato */}
193	      <div className="rounded-2xl border border-[#57715B]/20 bg-[#57715B]/5 p-4 flex gap-3">
194	        <Lock className="h-5 w-5 text-[#57715B] flex-shrink-0 mt-0.5" />
195	        <p className="text-sm text-[#57715B] dark:text-[#8FAE94]">
196	          Sua identidade é protegida. Não registramos quem você é, seu IP ou se está logado.
197	          Evite incluir informações que possam te identificar na mensagem.
198	        </p>
199	      </div>
200	
201	      {/* Honeypot — sr-only, nunca visto por humanos */}
202	      <div className="sr-only" aria-hidden="true">
203	        <input
204	          data-mia-skip
205	          tabIndex={-1}
206	          autoComplete="off"
207	          {...register('hp_field')}
208	        />
209	      </div>
210	
211	      {/* Categoria */}
212	      <div className="flex flex-col gap-1.5">
213	        <Label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
214	          Categoria <span className="text-red-500">*</span>
215	        </Label>
216	        <Select
217	          onValueChange={(v) => setValue('categoria', v as CategoriaOuvidoria, { shouldValidate: true })}
218	        >
219	          <SelectTrigger data-mia-skip className="bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus:ring-[#57715B]/30 rounded-xl h-11">
220	            <SelectValue placeholder="Selecione uma categoria" />
221	          </SelectTrigger>
222	          <SelectContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl">
223	            {CATEGORIAS_OUVIDORIA.map((cat) => (
224	              <SelectItem key={cat.value} value={cat.value}>
225	                {cat.label}
226	              </SelectItem>
227	            ))}
228	          </SelectContent>
229	        </Select>
230	        {errors.categoria && (
231	          <p className="text-xs text-red-500">{errors.categoria.message}</p>
232	        )}
233	      </div>
234	
235	      {/* Loja (opcional) */}
236	      <div className="flex flex-col gap-1.5">
237	        <Label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
238	          Loja relacionada <span className="text-muted-foreground font-normal">(opcional)</span>
239	        </Label>
240	        <Select onValueChange={(v) => setValue('loja_id', v)}>
241	          <SelectTrigger data-mia-skip className="bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus:ring-[#57715B]/30 rounded-xl h-11">
242	            <SelectValue placeholder="Prefiro não informar" />
243	          </SelectTrigger>
244	          <SelectContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl">
245	            <SelectItem value="__nao_informar">Prefiro não informar</SelectItem>
246	            {LOJAS_OUVIDORIA.map((loja) => (
247	              <SelectItem key={loja.id} value={String(loja.id)}>
248	                {loja.nome}
249	              </SelectItem>
250	            ))}
251	          </SelectContent>
252	        </Select>
253	      </div>
254	
255	      {/* Mensagem */}
256	      <div className="flex flex-col gap-1.5">
257	        <Label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
258	          Mensagem <span className="text-red-500">*</span>
259	        </Label>
260	        <textarea
261	          data-mia-skip
262	          {...register('mensagem')}
263	          rows={6}
264	          maxLength={5000}
265	          placeholder="Descreva o ocorrido com detalhes..."
266	          className="w-full resize-none rounded-xl bg-white/60 dark:bg-black/20 backdrop-blur-md border border-[#57715B]/15 px-3 py-2.5 text-sm text-[#2D362E] dark:text-[#E6DCCF] placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#57715B]/30 transition-shadow"
267	        />
268	        <div className="flex items-center justify-between">
269	          {errors.mensagem ? (
270	            <p className="text-xs text-red-500">{errors.mensagem.message}</p>
271	          ) : (
272	            <span />
273	          )}
274	          <span className="text-xs text-muted-foreground">
275	            {mensagemValue.length}/5.000
276	          </span>
277	        </div>
278	      </div>
279	
280	      {/* Senha de acompanhamento */}
281	      <div className="flex flex-col gap-1.5">
282	        <Label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
283	          Senha de acompanhamento <span className="text-red-500">*</span>
284	        </Label>
285	        <div className="relative">
286	          <Input
287	            data-mia-skip
288	            {...register('senha')}
289	            type={mostrarSenha ? 'text' : 'password'}
290	            placeholder="Mínimo 4 caracteres"
291	            className="bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl h-11 pr-10"
292	          />
293	          <button
294	            type="button"
295	            data-mia-skip
296	            onClick={() => setMostrarSenha((v) => !v)}
297	            className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-[#57715B] transition-colors"
298	            aria-label={mostrarSenha ? 'Ocultar senha' : 'Mostrar senha'}
299	          >
300	            {mostrarSenha ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
301	          </button>
302	        </div>
303	        <p className="text-xs text-muted-foreground">
304	          Anote esta senha — ela não pode ser recuperada depois.
305	        </p>
306	        {errors.senha && (
307	          <p className="text-xs text-red-500">{errors.senha.message}</p>
308	        )}
309	      </div>
310	
311	      <Button
312	        type="submit"
313	        disabled={enviarDenuncia.isPending}
314	        className="w-full bg-[#57715B] hover:bg-[#465b49] text-white rounded-xl h-11 gap-2 mt-1"
315	      >
316	        {enviarDenuncia.isPending ? (
317	          <Loader2 className="h-4 w-4 animate-spin" />
318	        ) : (
319	          <Send className="h-4 w-4" />
320	        )}
321	        {enviarDenuncia.isPending ? 'Enviando...' : 'Enviar denúncia'}
322	      </Button>
323	    </form>
324	  );
325	}
326	
327	// ---------------------------------------------------------------------------
328	// Sub-componente: Acompanhamento de protocolo
329	// ---------------------------------------------------------------------------
330	
331	interface FormAcompanharProps {
332	  protocoloInicial?: string;
333	}
334	
335	function FormAcompanhar({ protocoloInicial }: FormAcompanharProps) {
336	  const [resultado, setResultado] = useState<ConsultaProtocoloResult | null>(null);
337	  const [consultaAtual, setConsultaAtual] = useState<{ protocolo: string; senha: string } | null>(null);
338	  const [respostaTexto, setRespostaTexto] = useState('');
339	  const [mostrarSenha, setMostrarSenha] = useState(false);
340	
341	  const consultarProtocolo = useConsultarProtocolo();
342	  const responderProtocolo = useResponderProtocolo();
343	
344	  const {
345	    register,
346	    handleSubmit,
347	    formState: { errors },
348	  } = useForm<ConsultaFormValues>({
349	    resolver: zodResolver(consultaSchema),
350	    defaultValues: { protocolo: protocoloInicial ?? '' },
351	  });
352	
353	  const onConsultar = handleSubmit(async (values) => {
354	    try {
355	      const res = await consultarProtocolo.mutateAsync({
356	        protocolo: values.protocolo.trim().toUpperCase(),
357	        senha: values.senha,
358	      });
359	      setResultado(res);
360	      if (res.ok) {
361	        setConsultaAtual({ protocolo: values.protocolo.trim().toUpperCase(), senha: values.senha });
362	      }
363	    } catch (err) {
364	      toast.error((err as Error).message ?? 'Erro ao consultar protocolo');
365	    }
366	  });
367	
368	  const onResponder = async () => {
369	    if (!consultaAtual || !respostaTexto.trim()) return;
370	    try {
371	      await responderProtocolo.mutateAsync({
372	        protocolo: consultaAtual.protocolo,
373	        senha: consultaAtual.senha,
374	        mensagem: respostaTexto.trim(),
375	      });
376	      setRespostaTexto('');
377	      // Reconsultar após resposta
378	      const res = await consultarProtocolo.mutateAsync(consultaAtual);
379	      setResultado(res);
380	      toast.success('Mensagem enviada');
381	    } catch (err) {
382	      toast.error((err as Error).message ?? 'Erro ao enviar mensagem');
383	    }
384	  };
385	
386	  return (
387	    <div className="flex flex-col gap-5">
388	      {/* Formulário de consulta */}
389	      <form onSubmit={onConsultar} className="flex flex-col gap-4">
390	        <div className="flex flex-col gap-1.5">
391	          <Label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
392	            Protocolo
393	          </Label>
394	          <Input
395	            data-mia-skip
396	            {...register('protocolo')}
397	            placeholder="Ex.: OUV-20240101-XXXX"
398	            className="bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl h-11 font-mono uppercase"
399	          />
400	          {errors.protocolo && (
401	            <p className="text-xs text-red-500">{errors.protocolo.message}</p>
402	          )}
403	        </div>
404	
405	        <div className="flex flex-col gap-1.5">
406	          <Label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
407	            Senha
408	          </Label>
409	          <div className="relative">
410	            <Input
411	              data-mia-skip
412	              {...register('senha')}
413	              type={mostrarSenha ? 'text' : 'password'}
414	              placeholder="Sua senha de acompanhamento"
415	              className="bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl h-11 pr-10"
416	            />
417	            <button
418	              type="button"
419	              data-mia-skip
420	              onClick={() => setMostrarSenha((v) => !v)}
421	              className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-[#57715B] transition-colors"
422	              aria-label={mostrarSenha ? 'Ocultar senha' : 'Mostrar senha'}
423	            >
424	              {mostrarSenha ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
425	            </button>
426	          </div>
427	          {errors.senha && (
428	            <p className="text-xs text-red-500">{errors.senha.message}</p>
429	          )}
430	        </div>
431	
432	        <Button
433	          type="submit"
434	          disabled={consultarProtocolo.isPending}
435	          className="w-full bg-[#57715B] hover:bg-[#465b49] text-white rounded-xl h-11 gap-2"
436	        >
437	          {consultarProtocolo.isPending ? (
438	            <Loader2 className="h-4 w-4 animate-spin" />
439	          ) : null}
440	          {consultarProtocolo.isPending ? 'Consultando...' : 'Consultar protocolo'}
441	        </Button>
442	      </form>
443	
444	      {/* Resultado */}
445	      {resultado !== null && !resultado.ok && (
446	        <div className="rounded-2xl border border-red-200 dark:border-red-800/30 bg-red-50 dark:bg-red-900/10 p-4 text-sm text-red-600 dark:text-red-400">
447	          Protocolo ou senha incorretos.
448	        </div>
449	      )}
450	
451	      {resultado !== null && resultado.ok && (
452	        <div className="flex flex-col gap-4">
453	          {/* Cabeçalho da denúncia */}
454	          <GlassCard className="p-4 flex flex-col gap-3">
455	            <div className="flex flex-wrap items-center gap-2">
456	              <span className="font-mono text-sm font-bold text-[#57715B]">
457	                {resultado.denuncia.protocolo}
458	              </span>
459	              <CategoriaBadge categoria={resultado.denuncia.categoria} />
460	              <StatusBadge status={resultado.denuncia.status} />
461	            </div>
462	            <p className="text-xs text-muted-foreground">
463	              Registrada em{' '}
464	              {format(parseISO(resultado.denuncia.created_at), "dd/MM/yyyy 'às' HH:mm", {
465	                locale: ptBR,
466	              })}
467	            </p>
468	            <div className="border-t border-[#57715B]/10 pt-3">
469	              <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-1">
470	                Mensagem original
471	              </p>
472	              <p className="text-sm text-[#2D362E] dark:text-[#E6DCCF] whitespace-pre-wrap">
473	                {resultado.denuncia.mensagem}
474	              </p>
475	            </div>
476	          </GlassCard>
477	
478	          {/* Thread de mensagens */}
479	          {resultado.mensagens.length > 0 && (
480	            <div className="flex flex-col gap-3 py-2">
481	              <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
482	                Conversas
483	              </p>
484	              <div className="flex flex-col gap-3">
485	                {resultado.mensagens.map((msg, i) => (
486	                  <MensagemBubble key={i} mensagem={msg} />
487	                ))}
488	              </div>
489	            </div>
490	          )}
491	
492	          {/* Responder */}
493	          {resultado.denuncia.status !== 'resolvida' &&
494	            resultado.denuncia.status !== 'arquivada' && (
495	              <div className="flex flex-col gap-2">
496	                <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
497	                  Adicionar mensagem
498	                </p>
499	                <textarea
500	                  data-mia-skip
501	                  value={respostaTexto}
502	                  onChange={(e) => setRespostaTexto(e.target.value)}
503	                  rows={3}
504	                  placeholder="Adicione informações ou acompanhe o andamento..."
505	                  className="w-full resize-none rounded-xl bg-white/60 dark:bg-black/20 backdrop-blur-md border border-[#57715B]/15 px-3 py-2.5 text-sm text-[#2D362E] dark:text-[#E6DCCF] placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#57715B]/30 transition-shadow"
506	                />
507	                <Button
508	                  type="button"
509	                  data-mia-skip
510	                  onClick={onResponder}
511	                  disabled={!respostaTexto.trim() || responderProtocolo.isPending}
512	                  className="self-end bg-[#57715B] hover:bg-[#465b49] text-white rounded-xl h-9 px-4 gap-2 text-sm"
513	                >
514	                  {responderProtocolo.isPending ? (
515	                    <Loader2 className="h-3.5 w-3.5 animate-spin" />
516	                  ) : (
517	                    <Send className="h-3.5 w-3.5" />
518	                  )}
519	                  Enviar
520	                </Button>
521	              </div>
522	            )}
523	        </div>
524	      )}
525	    </div>
526	  );
527	}
528	
529	// ---------------------------------------------------------------------------
530	// Página principal
531	// ---------------------------------------------------------------------------
532	
