import { cn } from '@/shared/lib/utils';
import { labelStatus } from '../lib/categorias';
import type { StatusOuvidoria } from '../types';

interface StatusBadgeProps {
  status: StatusOuvidoria;
  className?: string;
}

const STATUS_CLASSES: Record<StatusOuvidoria, string> = {
  recebida: 'text-amber-600 bg-amber-50 dark:bg-amber-900/20 border-amber-200 dark:border-amber-800/30',
  em_analise: 'text-blue-600 bg-blue-50 dark:bg-blue-900/20 border-blue-200 dark:border-blue-800/30',
  resolvida: 'text-emerald-600 bg-emerald-50 dark:bg-emerald-900/20 border-emerald-200 dark:border-emerald-800/30',
  arquivada: 'text-zinc-500 bg-zinc-50 dark:bg-zinc-900/20 border-zinc-200 dark:border-zinc-800/30',
};

export function StatusBadge({ status, className }: StatusBadgeProps) {
  return (
    <span
      className={cn(
        'inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-semibold border',
        STATUS_CLASSES[status],
        className,
      )}
    >
      {labelStatus(status)}
    </span>
  );
}

