import { cn } from '@/shared/lib/utils';
import { labelCategoria } from '../lib/categorias';
import type { CategoriaOuvidoria } from '../types';

interface CategoriaBadgeProps {
  categoria: CategoriaOuvidoria;
  className?: string;
}

const CATEGORIA_CLASSES: Record<CategoriaOuvidoria, string> = {
  assedio_moral: 'text-red-600 bg-red-50 dark:bg-red-900/20 border-red-200 dark:border-red-800/30',
  assedio_sexual: 'text-red-700 bg-red-50 dark:bg-red-900/20 border-red-200 dark:border-red-800/30',
  fraude_financeiro: 'text-orange-600 bg-orange-50 dark:bg-orange-900/20 border-orange-200 dark:border-orange-800/30',
  discriminacao: 'text-purple-600 bg-purple-50 dark:bg-purple-900/20 border-purple-200 dark:border-purple-800/30',
  seguranca_trabalho: 'text-amber-600 bg-amber-50 dark:bg-amber-900/20 border-amber-200 dark:border-amber-800/30',
  conduta_etica: 'text-blue-600 bg-blue-50 dark:bg-blue-900/20 border-blue-200 dark:border-blue-800/30',
  sugestao: 'text-[#57715B] bg-[#57715B]/8 border-[#57715B]/20',
  outro: 'text-zinc-500 bg-zinc-50 dark:bg-zinc-900/20 border-zinc-200 dark:border-zinc-800/30',
};

export function CategoriaBadge({ categoria, className }: CategoriaBadgeProps) {
  return (
    <span
      className={cn(
        'inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-semibold border',
        CATEGORIA_CLASSES[categoria],
        className,
      )}
    >
      {labelCategoria(categoria)}
    </span>
  );
}

