import { format, parseISO } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { cn } from '@/shared/lib/utils';
import type { MensagemThread } from '../types';

interface MensagemBubbleProps {
  mensagem: MensagemThread;
}

export function MensagemBubble({ mensagem }: MensagemBubbleProps) {
  const isDenunciante = mensagem.autor === 'denunciante';
  const dataFormatada = format(parseISO(mensagem.created_at), "dd/MM/yyyy 'às' HH:mm", {
    locale: ptBR,
  });

  return (
    <div
      className={cn(
        'flex flex-col gap-1 max-w-[85%]',
        isDenunciante ? 'self-start items-start' : 'self-end items-end',
      )}
    >
      <span className="text-[10px] font-medium text-muted-foreground uppercase tracking-wide px-1">
        {isDenunciante ? 'Denunciante' : 'Ouvidoria'}
      </span>
      <div
        className={cn(
          'rounded-2xl px-4 py-3 text-sm leading-relaxed shadow-sm',
          isDenunciante
            ? 'bg-white/60 dark:bg-black/20 backdrop-blur-md border border-white/20 dark:border-white/10 text-[#2D362E] dark:text-[#E6DCCF]'
            : 'bg-[#57715B] text-white',
        )}
      >
        <p className="whitespace-pre-wrap break-words">{mensagem.mensagem}</p>
      </div>
      <span className="text-[10px] text-muted-foreground px-1">{dataFormatada}</span>
    </div>
  );
}

